prompts.raw:
function ({ vars }) {
  const systemPrompt = buildSystemPrompt({
    authorPrompt: OWN_AUTHOR_PROMPT,
    customPrompt: vars.customPrompt,
  });

  return [
    { role: 'system', content: `{% raw %}${systemPrompt}{% endraw %}` },
    { role: 'user', content: `{% raw %}${vars.request}{% endraw %}` },
  ];
}
